#!/usr/bin/env node
// Concatenates each city's many small per-place files into one data/japon/<city>.bundle.js.
// Generated at deploy time (see .github/workflows/pages.yml) — never committed to git, so it
// can never drift from the real per-place source files. For local testing, run this once:
//   node scripts/generate-bundles.js
//
// Why: ~90 separate <script> tags for Japan's place data all load on every page regardless of
// route. Bundling per city cuts that to 8 requests without changing what loads or when — every
// page still gets all the data it did before (needed for site-wide search), so this is a
// zero-risk request-count reduction, not the (riskier) "only load the current city" version.

const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const CITY_DIRS = ['kioto', 'nara', 'uji', 'miyajima', 'himeji', 'osaka', 'tokio', 'kamakura'];

for (const city of CITY_DIRS) {
  const dir = path.join(ROOT, 'data', 'japon', city);
  const files = fs.readdirSync(dir).filter(f => f.endsWith('.js')).sort();
  const parts = files.map(f => fs.readFileSync(path.join(dir, f), 'utf8'));
  const bundle = `// AUTO-GENERATED by scripts/generate-bundles.js — do not edit directly.\n// Source: data/japon/${city}/*.js (${files.length} files). Edit those, then regenerate.\n\n` + parts.join('\n');
  fs.writeFileSync(path.join(ROOT, 'data', 'japon', `${city}.bundle.js`), bundle);
  console.log(`${city}.bundle.js: ${files.length} files, ${(bundle.length / 1024).toFixed(0)}KB`);
}
